INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (101, N'Rolex Submariner Date 126610LN', N'Đồng hồ lặn huyền thoại với vỏ Oystersteel 41mm, mặt số đen Cerachrom, chống nước 300m. Bộ máy Calibre 3235 tự động, dự trữ năng lượng 70 giờ. Dây đeo Oyster với khóa Oysterlock an toàn và hệ thống điều chỉnh Glidelock.', 1000000.00, 3, N'https://images.unsplash.com/photo-1622434641406-a158123450f9?w=800', 1);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (102, N'Rolex Daytona 126500LN', N'Biểu tượng của tốc độ và đẳng cấp. Vỏ Oystersteel 40mm, bezel Cerachrom đen, mặt số Panda trắng. Bộ máy Calibre 4131 chronograph, dự trữ năng lượng 72 giờ. Chống nước 100m.', 3000000.00, 1, N'https://images.unsplash.com/photo-1547996160-81dfa63595aa?w=800', 1);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (103, N'Patek Philippe Nautilus 5711/1A-010', N'Chiếc đồng hồ thể thao sang trọng kinh điển. Vỏ thép không gỉ 40mm, mặt số xanh gradient, dây thép tích hợp. Bộ máy Calibre 26-330 S C tự động, chống nước 120m. Thiết kế bởi Gerald Genta.', 2000000.00, 1, N'https://images.unsplash.com/photo-1523170335258-f5ed11844a49?w=800', 1);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (104, N'Audemars Piguet Royal Oak 15500ST', N'Vỏ thép không gỉ 41mm, mặt số xanh Petite Tapisserie. Bộ máy Calibre 4302 tự động, dự trữ năng lượng 70 giờ. Thiết kế octagon với 8 ốc vít hexagonal đặc trưng. Chống nước 50m.', 1000000.00, 2, N'https://images.unsplash.com/photo-1614164185128-e4ec99c436d7?w=800', 1);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (105, N'Omega Speedmaster Moonwatch Professional', N'Chiếc đồng hồ đầu tiên lên Mặt Trăng. Vỏ thép 42mm, mặt số đen, kính Hesalite. Bộ máy Calibre 3861 METAS lên dây cót thủ công, dự trữ 50 giờ. Chronograph với tachymeter bezel.', 2000000.00, 5, N'https://images.unsplash.com/photo-1524592094714-0f0654e20314?w=800', 1);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (106, N'Omega Seamaster Diver 300M', N'Vỏ thép không gỉ 42mm, mặt số ceramic xanh biển. Bộ máy Master Chronometer 8800, chống từ 15,000 gauss. Chống nước 300m, van thoát khí helium. Dây cao su hoặc thép.', 100000.00, 7, N'https://images.unsplash.com/photo-1612817159949-195b6eb9e31a?w=800', 6);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (107, N'Casio G-Shock Mudmaster GWG-2000', N'Cấu trúc Carbon Core Guard siêu bền. Chống bùn, chống va đập, chống rung. Triple Sensor (la bàn, đo cao, khí áp/nhiệt độ). Năng lượng mặt trời, đồng bộ sóng radio Multiband 6.', 8500000.00, 25, N'https://images.unsplash.com/photo-1522312346375-d1a52e2b99b3?w=800', 2);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (108, N'Casio G-Shock GA-2100-1A1 ''CasiOak''', N'Thiết kế bát giác mỏng nhất dòng G-Shock chỉ 11.8mm. Vỏ nhựa carbon, chống va đập. Hiển thị analog-digital kết hợp. Pin CR2016 thời lượng 3 năm. Chống nước 200m.', 3200000.00, 50, N'https://images.unsplash.com/photo-1576420469891-b303889e81bf?w=800', 2);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (109, N'Seiko Prospex SPB143 ''62MAS Reissue''', N'Tái bản mẫu đồng hồ lặn đầu tiên của Seiko. Vỏ thép 40.5mm, mặt số xanh gradient. Bộ máy 6R35 tự động, dự trữ 70 giờ. Kính sapphire, chống nước 200m. Dây silicone.', 2800000.00, 12, N'https://images.unsplash.com/photo-1565250026886-ec2964652258?w=800', 6);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (110, N'Garmin Fenix 7X Pro Solar', N'Đồng hồ thể thao GPS cao cấp nhất của Garmin. Màn hình MIP 1.4 inch, sạc năng lượng mặt trời. Bản đồ TopoActive, đèn LED tích hợp. Pin lên đến 37 ngày (GPS), cảm biến SpO2, nhịp tim quang học.', 2290000.00, 15, N'https://images.unsplash.com/photo-1517502884422-41eaead166d4?w=800', 2);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (111, N'Apple Watch Ultra 2', N'Vỏ titanium 49mm, màn hình OLED 2000 nits. Chip S9, Double Tap, GPS L1+L5 chính xác cao. Chống nước 100m, đạt chuẩn EN13319 cho lặn. Pin 36 giờ sử dụng bình thường, 72 giờ tiết kiệm pin.', 2199000.00, 30, N'https://images.unsplash.com/photo-1704942968209-6c1e05ef3f95?w=800', 3);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (112, N'Samsung Galaxy Watch 6 Classic 47mm', N'Vòng bezel xoay cổ điển, màn hình Super AMOLED 1.5 inch. Chip Exynos W930, Wear OS, theo dõi giấc ngủ nâng cao. Cảm biến BioActive, đo nhiệt độ da, ECG, huyết áp. Pin 425mAh.', 990000.00, 35, N'https://images.unsplash.com/photo-1579586337278-3befd40fd17a?w=800', 3);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (113, N'Garmin Venu 3', N'Màn hình AMOLED 1.4 inch sáng rõ. Theo dõi sức khỏe toàn diện: Body Battery, Sleep Coach, HRV, Nap Detection. Hơn 30 ứng dụng thể thao tích hợp. Pin lên đến 14 ngày. Hỗ trợ nghe gọi Bluetooth.', 1000000.00, 20, N'https://images.unsplash.com/photo-1656955178167-3888ac44843c?w=800', 3);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (114, N'Tissot PRX Powermatic 80', N'Thiết kế retro-chic lấy cảm hứng từ thập niên 70. Vỏ thép 40mm, mặt số xanh lá waffle. Bộ máy Powermatic 80 tự động, dự trữ 80 giờ. Kính sapphire chống xước. Chống nước 100m.', 1600000.00, 18, N'https://images.unsplash.com/photo-1533139502658-0198f920d8e8?w=800', 4);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (115, N'Hamilton Khaki Field Mechanical', N'Đồng hồ quân đội kinh điển. Vỏ thép 38mm, mặt số đen matte. Bộ máy H-50 lên dây cót thủ công, dự trữ 80 giờ. Dây vải NATO olive. Kính sapphire, chống nước 50m.', 1250000.00, 14, N'https://images.unsplash.com/photo-1548171915-e79a380a2a4b?w=800', 4);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (116, N'Longines Master Collection Moonphase', N'Vỏ thép 40mm, mặt số trắng kem với chỉ báo trăng tròn lúc 6h. Bộ máy L899 tự động (base ETA), dự trữ 72 giờ. Kim xanh thép, index La Mã. Dây da cá sấu đen.', 5800000.00, 6, N'https://images.unsplash.com/photo-1542496658-e33a6d0d50f6?w=800', 4);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (117, N'Daniel Wellington Petite Sheffield 32mm', N'Thiết kế minimalist thanh lịch cho phái nữ. Vỏ thép mạ vàng hồng 32mm, mặt số trắng tinh khiết. Bộ máy Miyota quartz Nhật Bản. Dây da đen Italian. Chống nước 30m.', 4590000.00, 40, N'https://images.unsplash.com/photo-1524805444758-089113d48a6d?w=800', 5);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (118, N'Fossil Gen 6 Hybrid Wellness Edition', N'Kết hợp kim analog truyền thống và màn hình E-Ink. Theo dõi nhịp tim, SpO2, giấc ngủ. Pin 2 tuần. Kết nối Bluetooth, thông báo điện thoại. Vỏ thép 44mm, chống nước 50m.', 400000.00, 22, N'https://images.unsplash.com/photo-1613520701290-480b81948f43?w=800', 5);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (119, N'IWC Pilot''s Watch Mark XX', N'Vỏ thép 40mm, mặt số đen matte với triangle index lúc 12h. Bộ máy 32111 tự động (base Sellita), dự trữ 120 giờ. Kính sapphire chống phản chiếu, hệ thống bảo vệ từ trường.', 1150000.00, 4, N'https://images.unsplash.com/photo-1587925358603-c2eea5305bbc?w=800', 7);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (120, N'Breitling Navitimer B01 Chronograph 43', N'Biểu tượng hàng không với slide rule bezel. Vỏ thép 43mm, bộ máy in-house B01 chronograph, dự trữ 70 giờ. Mặt số đen với 3 subdial. Chống nước 30m. COSC Chronometer certified.', 1980000.00, 3, N'https://images.unsplash.com/photo-1509941943102-10c232535736?w=800', 7);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (121, N'Tudor Black Bay 58', N'Vỏ thép 39mm kích thước vintage hoàn hảo. Mặt số đen gilt, bezel đen nhôm. Bộ máy MT5402 COSC tự động, dự trữ 70 giờ. Chống nước 200m. Dây thép riveted style.', 89000.00, 8, N'https://images.unsplash.com/photo-1548169874-53e85f753f1e?w=800', 6);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (122, N'Citizen Promaster Eco-Drive BN0151-09L', N'Đồng hồ lặn năng lượng ánh sáng, không cần thay pin. Vỏ thép 44mm, mặt số xanh biển. Chống nước 200m ISO 6425. Dạ quang Lumi-Brite mạnh mẽ. Dây polyurethane bền bỉ.', 200000.00, 28, N'https://images.unsplash.com/photo-1776741929151-b3acce29f513?w=800', 6);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (123, N'Orient Bambino Version 2 FAC00005W0', N'Dress watch giá tốt nhất phân khúc. Vỏ thép 40.5mm, mặt số kem vintage, kim blued hands. Bộ máy F6722 tự động, dự trữ 40 giờ. Kính mineral dome. Dây da nâu.', 400000.00, 20, N'https://images.unsplash.com/photo-1689771495898-a564847768b6?w=800', 4);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (124, N'Xiaomi Watch S3', N'Màn hình AMOLED 1.43 inch, vỏ bezel có thể thay thế. HyperOS, hỗ trợ eSIM, GPS độc lập. Theo dõi 150+ bài tập, SpO2 24/7. Pin 486mAh, sử dụng 15 ngày. Chống nước 5ATM.', 3290000.00, 45, N'https://images.unsplash.com/photo-1461141346587-763ab02bced9?w=800', 3);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (125, N'Seiko 5 Sports SRPD55K1', N'Dòng đồng hồ tự động huyền thoại của Seiko. Vỏ thép 42.5mm, mặt số đen sunburst. Bộ máy 4R36 tự động, dự trữ 41 giờ, hacking & hand-winding. Chống nước 100m. Day-Date hiển thị.', 6800000.00, 30, N'https://images.unsplash.com/photo-1539874754764-5a96559165b0?w=800', 2);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (126, N'TAG Heuer Carrera Chronograph 44mm', N'Biểu tượng đua xe thể thao. Vỏ thép 44mm, mặt số đen với subdials bạc. Bộ máy Heuer 02 COSC in-house chronograph, dự trữ 80 giờ. Kính sapphire, caseback transparent.', 1280000.00, 5, N'https://images.unsplash.com/photo-1600721391776-b5cd0e0048f2?w=800', 2);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (127, N'Cartier Santos de Cartier Medium', N'Chiếc đồng hồ đeo tay đầu tiên trong lịch sử (1904). Vỏ thép 35.1mm, mặt số bạc guilloché, số La Mã xanh. Bộ máy 1847 MC tự động. Hệ thống QuickSwitch dây da/thép.', 1680000.00, 4, N'https://images.unsplash.com/photo-1526045431048-f857369baa09?w=800', 1);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (128, N'Junghans Max Bill Automatic', N'Thiết kế Bauhaus tinh khiết bởi nghệ sĩ Max Bill. Vỏ thép 38mm, mặt số trắng với font số đặc trưng. Bộ máy J800.1 tự động. Kính Plexiglas dome, dây da đen. Chống nước 30m.', 28500000.00, 10, N'https://images.unsplash.com/photo-1533139143976-30918502365b?w=800', 5);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (129, N'Bell & Ross BR 03-92 Diver', N'Đồng hồ lặn thiết kế vuông độc đáo lấy cảm hứng từ buồng lái máy bay. Vỏ thép 42mm, mặt số đen matte. Bộ máy BR-CAL.302 tự động. Chống nước 300m, bezel xoay một chiều.', 980000.00, 3, N'https://images.unsplash.com/photo-1585123334904-845d60e97b29?w=800', 7);
INSERT INTO [Products] ([Id], [Name], [Description], [Price], [Stock], [ImageUrl], [CategoryId]) VALUES (130, N'Casio Edifice ECB-2000DC-1A', N'Chronograph thể thao kết nối Bluetooth. Vỏ thép carbon 48mm, mặt số đen đa lớp. Năng lượng mặt trời Tough Solar. World time 300 thành phố, đồng bộ thời gian qua smartphone.', 8500000.00, 18, N'https://images.unsplash.com/photo-1495856458515-0637185db551?w=800', 2);
